import numpy as np
import math

def compute_order_amount(on_hand_inventory, pipeline_orders, last_demand, quoted_lead_time):
    base_target = 216.06792507951812  # OPT_PARAM: {"initial": 216.06792507951812, "min": 200.0, "max": 500.0, "type": "float"}
    demand_response_factor = 0.1  # OPT_PARAM: {"initial": 0.1, "min": 0.1, "max": 1.5, "type": "float"}
    pipeline_adjustment_factor = 1.0  # OPT_PARAM: {"initial": 1.0, "min": 0.5, "max": 1.0, "type": "float"}

    demand_based_adjustment = demand_response_factor * last_demand
    pipeline_adjustment = pipeline_adjustment_factor * sum(pipeline_orders)
    target = base_target + demand_based_adjustment - pipeline_adjustment

    order_amount = max(0.0, target - on_hand_inventory)
    return order_amount
